-- mistri store layout: decisions, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_decision_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_decision_record" (
  id TEXT COLLATE BINARY PRIMARY KEY,
  app TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(app AS BLOB)) <= 128),
  tenant TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(tenant AS BLOB)) <= 128),
  decision TEXT NOT NULL,
  contract_version INTEGER NOT NULL,
  resource TEXT NOT NULL,
  record_key TEXT NOT NULL,
  field TEXT NOT NULL,
  trigger TEXT NOT NULL,
  provider TEXT NOT NULL,
  model TEXT NOT NULL,
  model_version TEXT NOT NULL,
  inputs_digest TEXT NOT NULL,
  input_fields TEXT NOT NULL,
  choices_digest TEXT NOT NULL,
  answer TEXT CHECK (answer IS NULL OR length(CAST(answer AS BLOB)) <= 65536),
  probability REAL CHECK (probability IS NULL OR (probability >= 0 AND probability <= 1)),
  outcome TEXT NOT NULL CHECK (outcome IN ('applied', 'suggested', 'accepted', 'corrected', 'ignored', 'below', 'none')),
  outcome_reason TEXT NOT NULL,
  corrected_to TEXT,
  outcome_by TEXT NOT NULL,
  outcome_at TEXT NOT NULL,
  latency_ms INTEGER NOT NULL,
  cost_micros INTEGER NOT NULL,
  units INTEGER NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE "__mistri_decision_usage" (
  app TEXT COLLATE BINARY NOT NULL,
  tenant TEXT COLLATE BINARY NOT NULL,
  day TEXT NOT NULL,
  calls INTEGER NOT NULL,
  units INTEGER NOT NULL,
  cost_micros INTEGER NOT NULL,
  PRIMARY KEY (app, tenant, day)
);
CREATE INDEX "__mistri_decision_record_on" ON "__mistri_decision_record" (app, tenant, resource, record_key, created_at);
CREATE INDEX "__mistri_decision_record_age" ON "__mistri_decision_record" (app, created_at);
CREATE TABLE "__mistri_switch_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_switch_tenant" (
  app TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(app AS BLOB)) <= 128),
  tenant TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(tenant AS BLOB)) <= 128),
  feature TEXT COLLATE BINARY NOT NULL CHECK (length(CAST(feature AS BLOB)) <= 64),
  enabled INTEGER NOT NULL CHECK (enabled IN (0, 1)),
  consent TEXT NOT NULL CHECK (length(CAST(consent AS BLOB)) <= 2000),
  changed_at TEXT NOT NULL,
  PRIMARY KEY (app, tenant, feature)
);
